import React, { useState } from 'react';

function AuthScreen({ onBack }) {
  const [isLogin, setIsLogin] = useState(true);

  return (
    <div>
      <button className="btn btn-outline-secondary mb-4 fw-bold" onClick={onBack}>⬅ Quay lại trang chủ</button>
      <div className="card p-4 shadow border-0 mx-auto bg-white" style={{ maxWidth: '400px' }}>
        <h3 className="text-center fw-bold text-primary mb-4">{isLogin ? 'ĐĂNG NHẬP TÀI KHOẢN' : 'ĐĂNG KÝ THÀNH VIÊN'}</h3>
        
        <form onSubmit={(e) => { e.preventDefault(); alert(isLogin ? "Đăng nhập thành công!" : "Đăng ký thành công!"); onBack(); }}>
          <div className="mb-3">
            <label className="form-label fw-bold small text-secondary">Địa chỉ Email</label>
            <input type="email" className="form-control py-2" placeholder="name@example.com" required />
          </div>
          <div className="mb-3">
            <label className="form-label fw-bold small text-secondary">Mật khẩu</label>
            <input type="password" className="form-control py-2" placeholder="••••••••" required />
          </div>
          {!isLogin && (
            <div className="mb-3">
              <label className="form-label fw-bold small text-secondary">Nhập lại mật khẩu</label>
              <input type="password" className="form-control py-2" placeholder="••••••••" required />
            </div>
          )}
          <button type="submit" className="btn btn-primary w-100 fw-bold mt-3 py-2">{isLogin ? 'Đăng Nhập' : 'Đăng Ký'}</button>
        </form>
        
        <p className="text-center mt-4 mb-0 small text-primary fw-bold" style={{ cursor: 'pointer', textDecoration: 'underline' }} onClick={() => setIsLogin(!isLogin)}>
          {isLogin ? 'Chưa có tài khoản? Đăng ký ngay' : 'Đã có tài khoản thành viên? Đăng nhập'}
        </p>
      </div>
    </div>
  );
}

export default AuthScreen;
